// A report selects image bytes by immutable evidence SHA, never by a latest URL cache.
import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';import {gunzipSync} from 'node:zlib';import {writeImmutable} from './standalone-files.mjs';import {readArchivedFile} from './archived-state.mjs';
const hash=x=>createHash('sha256').update(x).digest('hex'),hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x),identity=row=>[row.key,hash(row.delivery.photo_url||''),String(row.delivery.raw_upload||row.delivery.upload||null)];
export async function retainCapturePhotoBindings(root,capture){const dir=path.join(root,'photo-version-bindings');await fs.mkdir(dir,{recursive:true,mode:0o700});for(const raw of capture.snapshot.rows){const p=capture.pointer.photos?.[raw.id];if(p?.status!=='captured'||!hex(p.sha256)||p.urlSha256!==hash(raw.proof?.photoUrl||'')||p.proofTimestamp!==(raw.proof?.timestamp??null))continue;const binding={recordKey:capture.day+'/'+raw.id,urlSha256:p.urlSha256,proofTimestamp:p.proofTimestamp,sha256:p.sha256};await writeImmutable(path.join(dir,hash(JSON.stringify(binding))+'.json'),Buffer.from(JSON.stringify(binding)));}}
export function pinPhotoRows({rows,previousRows=[],capture,captureIsCurrent=false,inventories=[]}){const previous=new Map(previousRows.map(row=>[row.key,row])),inventoryImages=new Map();for(const inventory of inventories)for(const item of inventory.queue.items){const digest=item.imageSha256||item.cachedSha256||inventory.proposals[item.id]?.imageSha256;if(!hex(digest))continue;for(const key of new Set([item.recordKey,item.datedRecordKey].filter(Boolean))){const identityKey=JSON.stringify([key,item.urlSha256,String(item.proofTimestamp??null)]),images=inventoryImages.get(identityKey)||new Set();images.add(digest);inventoryImages.set(identityKey,images);}}return rows.map(row=>{const d=row.delivery||{},id=row.key.slice(row.key.indexOf('/')+1),p=captureIsCurrent&&row.date===capture?.day&&!/^2026-10-(19|2[0-5])$/.test(row.date)?capture.pointer.photos?.[id]:null;let image=hex(d.photo_sha256)?d.photo_sha256:null;
 if(p?.status==='captured'&&hex(p.sha256)&&p.urlSha256===hash(d.photo_url||'')&&String(p.proofTimestamp??null)===String(d.raw_upload||d.upload||null))image=p.sha256;
 if(!image){const old=previous.get(row.key);if(old&&(old.assessmentHash===row.assessmentHash||captureIsCurrent&&row.date===capture?.day)&&JSON.stringify(identity(old))===JSON.stringify(identity(row))&&hex(old.delivery?.photo_sha256))image=old.delivery.photo_sha256;}
 if(!image){const found=inventoryImages.get(JSON.stringify(identity(row)));if(found?.size===1)image=[...found][0];}
 return image&&image!==d.photo_sha256?{...row,delivery:{...d,photo_sha256:image}}:row;});}
export async function readGenerationPhoto({root,archiveRoot,objectsRoot,row}){const digest=row.delivery?.photo_sha256;if(!hex(digest))return null;let bytes;try{const file=path.join(objectsRoot,digest),st=await fs.lstat(file);if(!st.isFile()||st.isSymbolicLink()||st.size>8*1024*1024)return null;bytes=await fs.readFile(file);}catch(e){if(e.code!=='ENOENT')throw e;try{bytes=gunzipSync(await readArchivedFile(root,archiveRoot,'photos/'+digest+'.gz'),{maxOutputLength:8*1024*1024});}catch(e){if(e.code==='ENOENT')return null;throw e;}}if(hash(bytes)!==digest)throw Error('Photo integrity failure');let mime;if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255)mime='image/jpeg';else if(bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))mime='image/png';else if(bytes.toString('ascii',0,4)==='RIFF'&&bytes.toString('ascii',8,12)==='WEBP')mime='image/webp';else throw Error('Unsupported retained image');return {bytes,mime,sha256:digest};}

// Resolve previously captured local bytes only while preparing a new report generation.
// Callers must persist the returned rows in that generation, never mutate an older one.
export async function recoverRetainedPhotoBindings({root,archiveRoot,objectsRoot,rows}){
 const wanted=new Map();for(const row of rows){const d=row.delivery||{},id=d.delivery_id;if(!id||row.key!==row.date+'/'+id||!d.photo_url)continue;const key=id+':'+hash(d.photo_url)+':'+String(d.raw_upload||d.upload||null);if(!wanted.has(key))wanted.set(key,[]);wanted.get(key).push({key:row.key,pinned:hex(d.photo_sha256)});}
 const bindings=new Map();let files;try{files=await fs.readdir(path.join(root,'photo-bindings'));}catch(e){if(e.code==='ENOENT')return {rows,recovered:0};throw e;}
 for(const file of files){if(!/^[a-f0-9]{64}\.json$/.test(file))continue;const location=path.join(root,'photo-bindings',file);let entry;try{const stat=await fs.lstat(location);if(!stat.isFile()||stat.isSymbolicLink()||stat.size>65536)continue;entry=JSON.parse(await fs.readFile(location));}catch{continue;}const m=entry.metadata,key=entry.key;if(typeof key!=='string'||hash(key)!==file.slice(0,64)||!wanted.has(key)||m?.status!=='captured'||!hex(m.sha256)||!hex(m.urlSha256))continue;const split=key.indexOf(':'),rest=key.slice(split+1),urlHash=rest.slice(0,64),clock=rest.slice(65);if(split<1||rest[64]!==':'||m.urlSha256!==urlHash||String(m.proofTimestamp??null)!==clock)continue;const set=bindings.get(key)||new Set();set.add(m.sha256);bindings.set(key,set);}
 const recovered=new Map();for(const [key,ids] of wanted){const hashes=bindings.get(key);if(ids.length!==1||ids[0].pinned||hashes?.size!==1)continue;const digest=[...hashes][0];let image;try{image=await readGenerationPhoto({root,archiveRoot,objectsRoot,row:{delivery:{photo_sha256:digest}}});}catch{continue;}if(image)recovered.set(ids[0].key,digest);}
 return {rows:rows.map(row=>recovered.has(row.key)?{...row,delivery:{...row.delivery,photo_sha256:recovered.get(row.key)}}:row),recovered:recovered.size};
}
